%root_path = fileparts(mfilename("fullpath"));
%root_path = pwd;
scuts_path = 'e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts';
Cutfitfile = fullfile(scuts_path,'GP_FFCutsFits.mat');

if ~exist('GP_FFCutsFits','var')
    ld = load(Cutfitfile);
    GP_FFCutsFits = ld.fit_src_struc;
end
fit_res_field = 'all_fit_par';

%%

[S_op11Ei200,J_op11Ei200,Gam_op11Ei200,S_op11Ei200q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei200_off110GPmiff_',fit_res_field]));
[S_op11Ei400,J_op11Ei400,Gam_op11Ei400,S_op11Ei400q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei400_off110GPminFF_',fit_res_field]));
[S_op11Ei800,J_op11Ei800,Gam_op11Ei800,S_op11Ei800q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei800_off110GPminFF_',fit_res_field]));

proj110minFF = GP_FFCutsFits.Ei200_off110GPmiff.data.proj;


[S_maEi800,J_maEi800,Gam_maEi800,S_maEi800q] = extract_fit_par( ...
    GP_FFCutsFits.(['Ei800_off200GPmaxFF_',fit_res_field]));
proj200maxFF = GP_FFCutsFits.Ei200_off200GPmaff.data.proj;

plot_fp('min FF change for low dE max FF for Ei800', ... %[output:group:7b4e549a] %[output:9e771d96] %[output:347a4e1c] %[output:2bea6ba6]
    [S_op11Ei200,S_op11Ei400,S_op11Ei800,S_maEi800], ... %[output:9e771d96] %[output:347a4e1c] %[output:2bea6ba6]
    [J_op11Ei200,J_op11Ei400,J_op11Ei800,J_maEi800], ... %[output:9e771d96] %[output:347a4e1c] %[output:2bea6ba6]
    [Gam_op11Ei200,Gam_op11Ei400,Gam_op11Ei800,Gam_maEi800]); %[output:group:7b4e549a] %[output:9e771d96] %[output:347a4e1c] %[output:2bea6ba6]
%%
bg_dataEi200 = extract_bg_par(GP_FFCutsFits.(['Ei200_off110GPmiff_',fit_res_field]),1);
bg_dataEi400 = extract_bg_par(GP_FFCutsFits.(['Ei400_off110GPminFF_',fit_res_field]),1);
bg_dataEi800mi = extract_bg_par(GP_FFCutsFits.(['Ei800_off110GPminFF_',fit_res_field]),1);
bg_dataEi800ma = extract_bg_par(GP_FFCutsFits.(['Ei800_off200GPmaxFF_',fit_res_field]),1);

plot_fp('line-q fit bg for different Ei',[], ... %[output:group:981d7022] %[output:2956d259]
    [bg_dataEi200,bg_dataEi400,bg_dataEi800mi,bg_dataEi800ma]) %[output:group:981d7022] %[output:2956d259]
%%
spp.Ei200_off110GPminNbg = GP_FFCutsFits.Ei200_off110GPmiff - ...
    sqw_eval(GP_FFCutsFits.Ei200_off110GPmiff,@linterp_bg,bg_dataEi200);
%plot(spp.Ei200_off110GPminNbg); lz 0 1; keep_figure %[output:95d5aedd]

spp.Ei400_off110GPminNbg = GP_FFCutsFits.Ei400_off110GPminFF - ...
    sqw_eval(GP_FFCutsFits.Ei400_off110GPminFF,@linterp_bg,bg_dataEi400);
%plot(spp.Ei400_off110GPminNbg); lz 0 1; keep_figure %[output:4581e729]

spp.Ei800_off110GPminNbg = GP_FFCutsFits.Ei800_off110GPminFF - ...
    sqw_eval(GP_FFCutsFits.Ei800_off110GPminFF,@linterp_bg,bg_dataEi800mi);
%plot(spp.Ei800_off110GPminNbg); lz 0 1; keep_figure %[output:70103b12]

spp.Ei800_off200GPmaxNbg = GP_FFCutsFits.Ei800_off200GPmaxFF - ...
    sqw_eval(GP_FFCutsFits.Ei800_off200GPmaxFF,@linterp_bg,bg_dataEi800ma);
%plot(spp.Ei800_off200GPmaxNbg); lz 0 0.1; keep_figure %[output:318923ce]
%%


%%
cuts_ranges = containers.Map();
cuts_ranges('Ei200_off110GPminNbg')  = [0;110];
cuts_ranges('Ei400_off110GPminNbg') = [110;160];
cuts_ranges('Ei800_off110GPminNbg') = [160;240];
cuts_ranges('Ei800_off200GPmaxNbg') = [240;460];

[w2,fh] = build_disp_in_dir_with_ds(spp,cuts_ranges,0.01,0.5,false); %[output:8b3c6498] %[output:78aefbf2]
data_ranges = cuts_ranges.values;
data_ranges  = [data_ranges{:}];
pan_data = struct('data_ranges',data_ranges,'combined_ds',w2);
%save('GP_0p50p50p5_data','pan_data');
fh.UserData = w2.data;

